# React Error Boundary Component

## Implementation

```tsx
// ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

// ─── Types ────────────────────────────────────────────────────────────────────

interface ErrorDetails {
  message: string;
  stack?: string;
  componentStack?: string;
  timestamp: string;
  errorId: string;
}

interface Props {
  children: ReactNode;
  /** Custom fallback UI — receives error details and a retry callback */
  fallback?: (details: ErrorDetails, retry: () => void) => ReactNode;
  /** Called whenever an error is caught (use for external logging / Sentry etc.) */
  onError?: (error: Error, info: ErrorInfo, details: ErrorDetails) => void;
  /** Shown in the default fallback so users know which section failed */
  componentName?: string;
}

interface State {
  hasError: boolean;
  details: ErrorDetails | null;
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

const generateErrorId = (): string =>
  `err_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;

const buildDetails = (error: Error, info: ErrorInfo): ErrorDetails => ({
  message: error.message || "An unknown error occurred",
  stack: error.stack,
  componentStack: info.componentStack ?? undefined,
  timestamp: new Date().toISOString(),
  errorId: generateErrorId(),
});

const logError = (
  error: Error,
  info: ErrorInfo,
  details: ErrorDetails
): void => {
  // ── Console output (structured for easy reading in DevTools) ──
  console.group(`🔴 [ErrorBoundary] ${details.errorId}`);
  console.error("Timestamp  :", details.timestamp);
  console.error("Message    :", details.message);
  console.error("Error obj  :", error);
  console.error("Stack trace:", details.stack);
  console.error("Component stack:", details.componentStack);
  console.groupEnd();

  // ── Persist to localStorage for post-mortem debugging ──
  try {
    const stored = JSON.parse(
      localStorage.getItem("errorBoundaryLogs") || "[]"
    ) as ErrorDetails[];

    // Keep only the last 20 entries to avoid bloat
    const updated = [...stored.slice(-19), details];
    localStorage.setItem("errorBoundaryLogs", JSON.stringify(updated));
  } catch {
    // localStorage might be unavailable (SSR, private browsing, quota exceeded)
  }
};

// ─── Default Fallback UI ──────────────────────────────────────────────────────

const DefaultFallback: React.FC<{
  details: ErrorDetails;
  retry: () => void;
  componentName?: string;
}> = ({ details, retry, componentName }) => {
  const [showDetails, setShowDetails] = React.useState(false);

  return (
    <div style={styles.wrapper} role="alert" aria-live="assertive">
      {/* Header */}
      <div style={styles.header}>
        <span style={styles.icon} aria-hidden="true">
          ⚠️
        </span>
        <h2 style={styles.title}>Something went wrong</h2>
      </div>

      {/* Context */}
      {componentName && (
        <p style={styles.context}>
          Error in <strong>{componentName}</strong>
        </p>
      )}

      {/* User-facing message */}
      <p style={styles.message}>{details.message}</p>

      {/* Actions */}
      <div style={styles.actions}>
        <button
          style={styles.retryButton}
          onClick={retry}
          onMouseOver={(e) =>
            ((e.currentTarget as HTMLButtonElement).style.backgroundColor =
              "#1d4ed8")
          }
          onMouseOut={(e) =>
            ((e.currentTarget as HTMLButtonElement).style.backgroundColor =
              "#2563eb")
          }
        >
          🔄 Retry
        </button>
        <button
          style={styles.detailsButton}
          onClick={() => setShowDetails((v) => !v)}
        >
          {showDetails ? "Hide" : "Show"} technical details
        </button>
      </div>

      {/* Technical details (collapsible) */}
      {showDetails && (
        <div style={styles.details}>
          <div style={styles.detailRow}>
            <span style={styles.detailLabel}>Error ID</span>
            <code style={styles.detailValue}>{details.errorId}</code>
          </div>
          <div style={styles.detailRow}>
            <span style={styles.detailLabel}>Time</span>
            <code style={styles.detailValue}>{details.timestamp}</code>
          </div>

          {details.stack && (
            <>
              <span style={styles.detailLabel}>Stack Trace</span>
              <pre style={styles.pre}>{details.stack}</pre>
            </>
          )}

          {details.componentStack && (
            <>
              <span style={styles.detailLabel}>Component Stack</span>
              <pre style={styles.pre}>{details.componentStack}</pre>
            </>
          )}
        </div>
      )}

      {/* Error ID footer */}
      <p style={styles.footer}>
        Reference ID: <code>{details.errorId}</code>
      </p>
    </div>
  );
};

// ─── Error Boundary Class ─────────────────────────────────────────────────────

class ErrorBoundary extends Component<Props, State> {
  static defaultProps: Partial<Props> = {
    componentName: undefined,
    fallback: undefined,
    onError: undefined,
  };

  state: State = { hasError: false, details: null };

  // Invoked during rendering — update state so next render shows the fallback
  static getDerivedStateFromError(error: Error): Partial<State> {
    return {
      hasError: true,
      // details will be completed in componentDidCatch (componentStack available there)
      details: {
        message: error.message || "An unknown error occurred",
        stack: error.stack,
        componentStack: undefined,
        timestamp: new Date().toISOString(),
        errorId: generateErrorId(),
      },
    };
  }

  // Invoked after rendering — perform side effects (logging, reporting)
  componentDidCatch(error: Error, info: ErrorInfo): void {
    const details = buildDetails(error, info);

    // Merge the complete componentStack into state
    this.setState({ details });

    // Internal logging
    logError(error, info, details);

    // External / custom logging hook
    this.props.onError?.(error, info, details);
  }

  retry = (): void => {
    this.setState({ hasError: false, details: null });
  };

  render(): ReactNode {
    const { hasError, details } = this.state;
    const { children, fallback, componentName } = this.props;

    if (hasError && details) {
      // Prefer custom fallback if provided
      if (fallback) {
        return fallback(details, this.retry);
      }

      return (
        <DefaultFallback
          details={details}
          retry={this.retry}
          componentName={componentName}
        />
      );
    }

    return children;
  }
}

export default ErrorBoundary;

// ─── Inline Styles ────────────────────────────────────────────────────────────

const styles: Record<string, React.CSSProperties> = {
  wrapper: {
    maxWidth: 640,
    margin: "2rem auto",
    padding: "1.5rem",
    borderRadius: 8,
    border: "1px solid #fca5a5",
    backgroundColor: "#fff1f2",
    fontFamily: "system-ui, sans-serif",
    color: "#1f2937",
  },
  header: {
    display: "flex",
    alignItems: "center",
    gap: "0.5rem",
    marginBottom: "0.75rem",
  },
  icon: { fontSize: "1.5rem" },
  title: { margin: 0, fontSize: "1.2rem", color: "#b91c1c" },
  context: { margin: "0 0 0.5rem", fontSize: "0.9rem", color: "#6b7280" },
  message: {
    margin: "0 0 1rem",
    padding: "0.75rem",
    borderRadius: 6,
    backgroundColor: "#fee2e2",
    color: "#991b1b",
    fontSize: "0.95rem",
  },
  actions: { display: "flex", gap: "0.75rem", flexWrap: "wrap" },
  retryButton: {
    padding: "0.5rem 1.25rem",
    border: "none",
    borderRadius: 6,
    backgroundColor: "#2563eb",
    color: "#fff",
    fontSize: "0.95rem",
    cursor: "pointer",
    transition: "background-color 0.2s",
  },
  detailsButton: {
    padding: "0.5rem 1.25rem",
    border: "1px solid #d1d5db",
    borderRadius: 6,
    backgroundColor: "#fff",
    color: "#374151",
    fontSize: "0.95rem",
    cursor: "pointer",
  },
  details: {
    marginTop: "1rem",
    padding: "1rem",
    borderRadius: 6,
    backgroundColor: "#f9fafb",
    border: "1px solid #e5e7eb",
  },
  detailRow: {
    display: "flex",
    gap: "0.5rem",
    alignItems: "baseline",
    marginBottom: "0.5rem",
  },
  detailLabel: {
    minWidth: 110,
    fontSize: "0.8rem",
    fontWeight: 600,
    color: "#6b7280",
    textTransform: "uppercase",
  },
  detailValue: { fontSize: "0.85rem", color: "#111827" },
  pre: {
    margin: "0.5rem 0 1rem",
    padding: "0.75rem",
    overflow: "auto",
    fontSize: "0.78rem",
    lineHeight: 1.5,
    backgroundColor: "#111827",
    color: "#f9fafb",
    borderRadius: 4,
    whiteSpace: "pre-wrap",
    wordBreak: "break-all",
  },
  footer: {
    marginTop: "1rem",
    fontSize: "0.78rem",
    color: "#9ca3af",
    textAlign: "right",
  },
};
```

