## Usage Examples

### 1 — Basic usage

```tsx
// App.tsx
import ErrorBoundary from "./ErrorBoundary";

export default function App() {
  return (
    <ErrorBoundary componentName="Dashboard">
      <Dashboard />
    </ErrorBoundary>
  );
}
```

### 2 — With external error reporting (e.g. Sentry)

```tsx
import * as Sentry from "@sentry/react";
import ErrorBoundary from "./ErrorBoundary";

<ErrorBoundary
  componentName="UserProfile"
  onError={(error, info, details) => {
    Sentry.captureException(error, {
      extra: {
        componentStack: info.componentStack,
        errorId: details.errorId,
        timestamp: details.timestamp,
      },
    });
  }}
>
  <UserProfile />
</ErrorBoundary>;
```

### 3 — Custom fallback UI

```tsx
<ErrorBoundary
  fallback={(details, retry) => (
    <div className="my-custom-error">
      <h3>Oops! {details.message}</h3>
      <small>ID: {details.errorId}</small>
      <button onClick={retry}>Try again</button>
    </div>
  )}
>
  <PaymentForm />
</ErrorBoundary>
```

### 4 — Testing with a bomb component

```tsx
function Bomb({ shouldThrow }: { shouldThrow: boolean }) {
  if (shouldThrow) throw new Error("💣 Intentional test error");
  return <p>All good!</p>;
}

export default function Demo() {
  const [explode, setExplode] = React.useState(false);
  return (
    <ErrorBoundary componentName="Demo">
      <button onClick={() => setExplode(true)}>Trigger error</button>
      <Bomb shouldThrow={explode} />
    </ErrorBoundary>
  );
}
```

---

## Architecture Summary

| Feature | Implementation |
|---|---|
| Error catching | `getDerivedStateFromError` + `componentDidCatch` |
| Fallback UI | Default with collapsible details; or inject your own via `fallback` prop |
| Retry | Resets `hasError` / `details` state to re-mount children |
| Console logging | Grouped, structured `console.error` output |
| Persistence | Last 20 errors saved to `localStorage` (key: `errorBoundaryLogs`) |
| External logging | `onError` prop receives `(error, info, details)` |
| Accessibility | `role="alert"` + `aria-live="assertive"` on fallback wrapper |
| TypeScript | Fully typed props, state, and helper functions |
